'use strict';
const STORE='thara-journal-v2', $=id=>document.getElementById(id);let state={current:0,sessions:{}},screen='today',viewed=0,timerEnd=0,timerInterval=null,restoreFocus=null;try{const raw=JSON.parse(localStorage.getItem(STORE)||'null');if(raw&&raw.sessions&&Number.isInteger(raw.current)&&raw.current>=0&&raw.current<20)state=raw}catch{}let storageOk=true;let numberPicker=null;
const icons={arrow:'<span aria-hidden="true">→</span>',check:'<span aria-hidden="true">✓</span>'};
const DAYS=[
{title:'Lower body',subtitle:'Quads, hamstrings & balance',short:'Lower',ex:[['Supported sit-to-stand','8–10','Use a stable bench and a fixed hand support. Stand smoothly; choose a comfortable depth.'],['Seated leg extension','10–12','Align your knees with the machine pivot. Keep your back supported and lower slowly.'],['Seated leg curl','10–12','Adjust the seat to your leg length. Keep hips against the pad and move within a comfortable range.'],['Supported calf raise','12–15','Hold a fixed rail. Rise and lower slowly, without leaning or bouncing.']]},
{title:'Upper body',subtitle:'Chest, back & arms',short:'Upper',ex:[['Chest-supported row','10–12','Keep your chest on the pad. Draw elbows back without lifting your torso.'],['Seated chest press','10–12','Set handles around mid-chest. Keep your back supported; do not force an arch.'],['Lat pulldown','10–12','Pull toward your upper chest. Keep the load light enough to avoid swinging or leaning back.'],['Supported biceps curl','12–15','Use a preacher pad or curl machine. Keep your upper arms still.']]},
{title:'Lower body',subtitle:'Hamstrings & hip control',short:'Lower',ex:[['Seated leg curl','10–12','Keep hips against the pad. Curl and return with control.'],['Low supported step-up','8 each side','Choose a low, stable step and hold a rail. Keep movement controlled and skip if symptoms increase.'],['Seated hip abduction','12–15','Keep your back against the support. Use a small, comfortable range with no swinging.'],['Supported calf raise','12–15','Hold a fixed support. Pause briefly at the top, then lower slowly.']]},
{title:'Upper body',subtitle:'Shoulders, chest & back',short:'Upper',ex:[['Seated chest press','10–12','Keep your back supported and finish before your technique changes.'],['Chest-supported row','10–12','Keep chest on the pad. Avoid shrugging or using torso momentum.'],['Seated lateral raise','12–15','Use a supported seat and light dumbbells. Lift only to a comfortable height.'],['Reverse pec deck','12–15','Keep chest against the pad and shoulders relaxed. Move slowly.'],['Supported triceps machine','10–12','Adjust the seat so you can extend your elbows without arching your back.']]},
{title:'Full body',subtitle:'A lighter finish to the week',short:'Full',ex:[['Supported sit-to-stand','8–10','Use a stable bench and hand support. Keep this easier than Day 1.'],['Seated leg curl','10–12','Comfortable range and a steady tempo. Do not lift your hips.'],['Seated chest press','10–12','Choose a lighter load than your upper-body sessions.'],['Chest-supported row','10–12','Keep your torso supported throughout. Leave at least four good repetitions in reserve.']]}
];
function greeting(hour=new Date().getHours()){return hour<12?'Good morning':hour<17?'Good afternoon':'Good evening'}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function getSession(n=state.current){return state.sessions[n]||(state.sessions[n]={sets:{},tasks:{},loads:{},reps:{},notes:'',cardio:0,feeling:'',mode:null,started:null,finished:null,ended:false})}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));storageOk=true}catch{storageOk=false;$('storageNotice').hidden=false;$('storageNotice').textContent='Saving is unavailable in this browser. Export your journal from the menu before closing.'}}
function currentSession(){return getSession(viewed)}
function dayPlan(n,mode){const p=DAYS[n%5];if(mode==='flare')return {...p,title:'Recovery day',subtitle:'Keep movement comfortable',ex:[],recovery:true};if(mode==='caution'&&[0,2,4].includes(n%5))return {...p,title:'Easy movement',subtitle:'A lighter Day '+(n+1),ex:[],recovery:true};if(mode==='caution')return {...p,ex:p.ex.filter(e=>e[0]!=='Lat pulldown'),gentle:true};return p}
function setCount(n,s){return s.mode==='caution'||Math.floor(n/5)===3?1:2}
function tasksFor(n,s){const p=dayPlan(n,s.mode);if(p.recovery)return s.mode==='flare'?[{id:'checkin',name:'Check in with yourself',detail:'Rest comfortably or try a short walk if it feels better. There is no movement target.'}]:[{id:'walk',name:'Easy flat walk',detail:'Try up to 5–10 minutes only if comfortable. Shorter is fine.'},{id:'checkin',name:'Check your response',detail:'Note how you feel afterward. Arrange an assessment for recurring exercise-triggered pain.'}];const result=[{id:'warmup',name:'Warm up',detail:'5–8 min easy movement, then a light practice set of each lift.'}];result.push({id:'cardio',name:'Cardio',detail:s.mode==='caution'?'Optional easy flat walk. Start with 5–10 minutes if comfortable.':'20–30 min flat walking or comfortable cycling. Keep a conversational pace; build toward the target gradually.'});if(s.mode==='ready'&&[0,2,4].includes(n%5))result.push({id:'core',name:'Core',detail:'Up to 15 min if consistent with your assessment advice: dead bug 6/side, bird dog 6/side, side plank from knees 10–20 sec/side. Begin with one round; build to three. Rest as needed. Skip provoking movements.'});result.push({id:'cooldown',name:'Cool down',detail:'3–5 min easy walking and relaxed breathing. No forced stretches.'});return result}
function sessionStats(n){const s=getSession(n),p=dayPlan(n,s.mode),tasks=tasksFor(n,s);let setKeys=[];p.ex.forEach((_,i)=>{for(let j=0;j<setCount(n,s);j++)setKeys.push(i+'-'+j)});const doneSets=setKeys.filter(k=>s.sets[k]).length,doneTasks=tasks.filter(t=>s.tasks[t.id]).length;return {done:doneSets+doneTasks,total:setKeys.length+tasks.length,sets:doneSets,exercises:p.ex.length,cardio:Number(s.cardio)||0}}
function formatDay(n){return String(n+1).padStart(2,'0')}
function weekStrip(n,interactive=false){const start=Math.floor(n/5)*5;return '<div class="weekstrip">'+DAYS.map((p,i)=>{const k=start+i,s=state.sessions[k],cls=(k===n?' current':'')+(s?.finished?' done':'');return `<button class="day-dot${cls}" data-action="preview" data-n="${k}" aria-label="Day ${k+1}, ${p.title}${s?.finished?', completed':''}" ${k===n?'aria-current="step"':''}><b>${s?.finished?'✓':k+1}</b><small>${p.short}</small></button>`}).join('')+'</div>'}
function nav(){['Today','Progress'].forEach(t=>{if(screen.toLowerCase()==='progress'&&t==='Progress'||screen.toLowerCase()!=='progress'&&t==='Today')$('tab'+t).setAttribute('aria-current','page');else $('tab'+t).removeAttribute('aria-current')})}
function updateGreeting(){if($('greeting'))$('greeting').textContent=greeting()+', Thara.'}
function render(){updateGreeting();nav();if(screen==='progress'){renderProgress();return}if(screen==='workout'){renderWorkout();return}renderHome()}
function renderHome(){viewed=state.current;const n=state.current,s=getSession(n),p=DAYS[n%5],stats=sessionStats(n),date=new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});$('main').innerHTML=`<div class="date">${esc(date)}</div><p class="muted small">${s.finished?'Your session is in the journal.':s.started?'Your session is right where you left it.':'Let’s start with Day '+(n+1)+'.'}</p><section class="session"><div class="session-inner"><div class="flex"><span class="overline">Day ${formatDay(n)} <span style="opacity:.5">/ 20</span></span><span class="pill">Week ${Math.floor(n/5)+1}</span></div><h2>${p.title}</h2><p>${p.subtitle}</p><button class="primary" data-action="start">${s.finished?'View completed session':s.ended?'Review session':s.started?'Continue session':'Start Day '+(n+1)} ${icons.arrow}</button><button class="text-button share-home" data-action="whatsapp">Send to WhatsApp ↗</button>${s.started&&!s.finished?`<p class="small" style="margin:13px 0 0">${stats.done} of ${stats.total} steps logged</p>`:''}</div><div class="session-footer"><div><strong>${p.ex.length} exercises</strong>Planned strength</div><div><strong>20–30 min</strong>Cardio goal</div><div><strong>${[0,2,4].includes(n%5)?'15 min':'Rest day'}</strong>Core goal</div></div></section><div class="flex section-head"><h3>This week</h3><span class="muted small">${Object.entries(state.sessions).filter(([k,v])=>Math.floor(+k/5)===Math.floor(n/5)&&v.finished).length} / 5 complete</span></div>${weekStrip(n)}<p class="help">Days follow your pace, not the calendar. Rest days are yours to take.</p>${s.ended?`<button class="secondary" data-action="next">${n===19?'View your progress':'Go to Day '+(n+2)} ${icons.arrow}</button>`:''}<div class="note"><strong style="color:var(--ink)">A quick check before training</strong><br>Choose today’s session based on how you feel. If back pain keeps returning, get it assessed and avoid pushing through worsening symptoms.<br><button class="text-button" data-action="approach">How this plan works ↗</button></div>`}
function openSheet(html){restoreFocus=document.activeElement;$('sheet').innerHTML='<div class="handle"></div><div style="text-align:right"><button class="icon-button" data-action="close" aria-label="Close dialog">✕</button></div>'+html;$('overlay').hidden=false;document.body.style.overflow='hidden';$('sheet').focus()}
function closeSheet(){numberPicker=null;$('overlay').hidden=true;document.body.style.overflow='';if(restoreFocus?.isConnected)restoreFocus.focus()}
function checkin(){openSheet(`<span class="overline">Day ${formatDay(state.current)} · Before you start</span><h2 id="sheetTitle">How are you feeling?</h2><p class="muted small">Pick the option that fits today. We’ll keep the session appropriate.</p><button class="choice" data-action="mode" data-mode="caution"><strong>Back pain keeps returning</strong><span>I haven’t had it assessed yet. Keep today gentle.</span></button><button class="choice" data-action="mode" data-mode="ready"><strong>Ready for a gradual return</strong><span>I’ve been assessed and advised I can resume this type of training. I’ll follow any individual limits.</span></button><button class="choice" data-action="mode" data-mode="flare"><strong>My pain is flaring today</strong><span>Make this a recovery day, with no loaded workout.</span></button><p class="help">Feeling fine at rest alone isn’t a reason to repeat a workout that brings pain back.</p>`)}
function startMode(mode){if(!['caution','ready','flare'].includes(mode))return;const s=getSession();if(s.mode&&s.mode!==mode){s.byMode=s.byMode||{};s.byMode[s.mode]={sets:s.sets,tasks:s.tasks,loads:s.loads,reps:s.reps,cardio:s.cardio};const prior=s.byMode[mode]||{sets:{},tasks:{},loads:{},reps:{},cardio:0};Object.assign(s,prior);stopTimer()}s.mode=mode;s.started=s.started||new Date().toISOString();save();closeSheet();viewed=state.current;screen='workout';render();window.scrollTo(0,0)}
function pickerValues(field,existing){const values=field==='load'?Array.from({length:2001},(_,i)=>i/2):field==='reps'?Array.from({length:100},(_,i)=>i+1):Array.from({length:301},(_,i)=>i);if(existing!==''&&existing!==undefined&&Number.isFinite(Number(existing))&&!values.includes(Number(existing)))values.push(Number(existing));return values.sort((a,b)=>a-b)}
function openNumberPicker(field,key){const s=currentSession();if(s.ended||!['load','reps','cardio'].includes(field))return;const exercise=dayPlan(viewed,s.mode).ex[Number((key||'0').split('-')[0])];const existing=field==='cardio'?s.cardio:field==='load'?s.loads[key]:s.reps[key];const fallback=field==='reps'?Number(exercise?.[1].match(/\d+/)?.[0]||8):field==='cardio'?20:0;const chosen=existing!==''&&existing!==undefined?Number(existing):fallback;const values=pickerValues(field,existing);const index=Math.max(0,values.indexOf(chosen));numberPicker={field,key,index,values,opened:Array.from(document.querySelectorAll('details.block[open]')).map(el=>el.querySelector('h3')?.textContent)};const title=field==='load'?'Choose weight':field==='reps'?'Choose reps':'Cardio minutes',unit=field==='load'?'kg':field==='reps'?'reps':'min';openSheet(`<span class="overline">${field==='cardio'?'Session total':esc(exercise?.[0]||'Working set')+' · Set '+(Number(key.split('-')[1])+1)}</span><h2 id="sheetTitle">${title}</h2><p class="small muted">Scroll to select, then tap Done.</p><div class="wheel-wrap"><div class="wheel-band" aria-hidden="true"></div><div id="numberWheel" class="number-wheel" role="listbox" aria-label="${title}" tabindex="0" aria-activedescendant="wheel-option-${index}">${values.map((v,i)=>`<div class="wheel-option" id="wheel-option-${i}" role="option" aria-selected="${i===index}" data-action="wheelOption" data-index="${i}">${v}<span>${unit}</span></div>`).join('')}</div></div><div class="flex picker-actions"><button class="secondary" data-action="numberClear">Clear</button><button class="primary" data-action="numberDone">Done</button></div>`);const wheel=$('numberWheel');wheel.scrollTop=index*48;wheel.addEventListener('scroll',()=>{if(!numberPicker)return;setPickerIndex(Math.round(wheel.scrollTop/48))},{passive:true});wheel.addEventListener('keydown',e=>{if(!numberPicker)return;let next=numberPicker.index;const keys={ArrowDown:1,ArrowUp:-1,PageDown:5,PageUp:-5};if(e.key in keys)next+=keys[e.key];else if(e.key==='Home')next=0;else if(e.key==='End')next=numberPicker.values.length-1;else if(e.key==='Enter'){e.preventDefault();commitNumberPicker();return}else return;e.preventDefault();setPickerIndex(next);wheel.scrollTo({top:numberPicker.index*48,behavior:'auto'})});}
function setPickerIndex(index){if(!numberPicker)return;const p=numberPicker;index=Math.max(0,Math.min(p.values.length-1,index));const old=$('wheel-option-'+p.index);old?.setAttribute('aria-selected','false');p.index=index;$('wheel-option-'+index)?.setAttribute('aria-selected','true');$('numberWheel')?.setAttribute('aria-activedescendant','wheel-option-'+index)}
function commitNumberPicker(clear=false){if(!numberPicker)return;const p=numberPicker,s=currentSession();if(s.ended)return;const value=clear?'':p.values[p.index];if(p.field==='cardio')s.cardio=clear?0:value;else if(p.field==='load')s.loads[p.key]=value;else s.reps[p.key]=value;save();closeSheet();renderWorkout();document.querySelectorAll('details.block').forEach(el=>{if(p.opened.includes(el.querySelector('h3')?.textContent))el.open=true});}
function demoLink(name,withName=false){const query=name+' exercise proper form tutorial';return `<a class="demo-link${withName?' demo-named':''}" href="https://www.youtube.com/results?search_query=${encodeURIComponent(query)}" target="_blank" rel="noopener noreferrer" aria-label="Find ${esc(name)} demonstrations on YouTube" title="YouTube demonstrations: ${esc(name)}"><svg viewBox="0 0 20 20" width="15" height="15" aria-hidden="true"><rect x="1" y="3" width="18" height="14" rx="4" fill="currentColor"/><path d="M8 6.5 13 10l-5 3.5z" fill="var(--paper)"/></svg>${withName?'<span>'+esc(name)+'</span>':''}</a>`}
function taskHTML(t,s){return `<button class="task-check" data-action="task" data-id="${t.id}" aria-pressed="${!!s.tasks[t.id]}" ${s.ended?'disabled':''}><span class="square" aria-hidden="true">✓</span><span>${t.name}<small>${t.detail}</small></span></button>${t.id==='core'?'<div class="core-demos">'+['Dead bug','Bird dog','Side plank from knees'].map(name=>demoLink(name,true)).join('')+'</div>':''}`}
function renderWorkout(){const n=viewed,s=getSession(n),p=dayPlan(n,s.mode),stats=sessionStats(n),tasks=tasksFor(n,s),count=setCount(n,s),locked=s.ended;const warm=tasks.filter(t=>t.id==='warmup'),extras=tasks.filter(t=>t.id!=='warmup');$('main').innerHTML=`<button class="text-button back" data-action="today">← Back to today</button><div class="flex"><span class="overline">Day ${formatDay(n)} · Week ${Math.floor(n/5)+1}</span><button class="text-button" data-action="approach">Plan notes</button></div><h1 class="work-title">${p.title}</h1><p class="muted small">${p.subtitle}</p><div class="flex small"><span id="workProgress">${stats.done} / ${stats.total} steps</span><span class="muted">${locked?'Saved session':'Auto-saved on this phone'}</span></div><div class="bar" role="progressbar" aria-label="Session progress" aria-valuemin="0" aria-valuemax="${stats.total}" aria-valuenow="${stats.done}"><span id="progressFill" style="width:${stats.done/stats.total*100}%"></span></div>${s.mode!=='ready'?`<div class="notice">${p.recovery?'Loaded leg work is on hold. Today is about comfortable movement and recording how you feel.':'Start with one light set. Use supported positions and stop any exercise that worsens your symptoms.'}${!locked?'<br><button class="text-button" data-action="checkin">Change today’s check-in</button>':''}</div>`:'<p class="small muted">'+weekAdvice(n)+' Rest 90–120 sec between sets. Keep at least 3–4 good reps in reserve.</p>'}<div>${warm.map(t=>taskHTML(t,s)).join('')}</div>${p.ex.map((e,i)=>{const all=Array.from({length:count},(_,j)=>s.sets[i+'-'+j]).every(Boolean);return `<details class="block ${all?'is-done':''}" ${i===0&&!locked?'open':''}><summary><span class="num">${all?'✓':String(i+1).padStart(2,'0')}</span><div><div class="exercise-heading"><h3>${e[0]}</h3>${demoLink(e[0])}</div><span class="muted small">${count} ${count===1?'set':'sets'} · ${e[1]} reps</span></div></summary><p class="exercise-info">${e[2]}</p>${exerciseTools(n,s,e,i)}<div class="table-head"><span>Set</span><span>kg</span><span>Reps</span><span>Done</span></div>${Array.from({length:count},(_,j)=>{const k=i+'-'+j;return `<div class="setrow ${s.sets[k]?'completed':''}"><span class="setnum">${j+1}</span><button class="number-field ${s.loads[k]===undefined||s.loads[k]===''?'placeholder':''}" data-action="number" data-field="load" data-key="${k}" aria-label="${e[0]}, set ${j+1}, weight ${s.loads[k]??'not logged'} kilograms. Choose weight" aria-haspopup="dialog" ${locked?'disabled':''}>${esc(s.loads[k]??'')}<span class="number-hint">${s.loads[k]===undefined||s.loads[k]===''?'0':''}</span></button><button class="number-field ${s.reps[k]===undefined||s.reps[k]===''?'placeholder':''}" data-action="number" data-field="reps" data-key="${k}" aria-label="${e[0]}, set ${j+1}, ${s.reps[k]||'reps not logged'}. Choose repetitions" aria-haspopup="dialog" ${locked?'disabled':''}>${esc(s.reps[k]??'')}<span class="number-hint">${s.reps[k]===undefined||s.reps[k]===''?e[1].split('–')[0].split(' ')[0]:''}</span></button><button class="check" data-action="set" data-key="${k}" aria-pressed="${!!s.sets[k]}" aria-label="${s.sets[k]?'Undo':'Complete'} ${e[0]} set ${j+1}" ${locked?'disabled':''}>✓</button></div>`}).join('')}</details>`}).join('')}<div id="rest" class="timer-small" ${timerEnd>Date.now()?'':'hidden'}><span>Rest <strong id="restTime">01:30</strong></span><button data-action="timerStop">Skip timer</button></div><div class="block"><span class="overline">${p.recovery?'Today’s check-in':'Finish your session'}</span>${extras.map(t=>taskHTML(t,s)).join('')}${!p.recovery?`<label class="inline-input">Cardio logged <button class="number-field minutes-field" data-action="number" data-field="cardio" aria-label="Cardio minutes, ${s.cardio||0}. Choose minutes" aria-haspopup="dialog" ${locked?'disabled':''}>${esc(s.cardio||0)}</button> min</label>`:''}</div><div class="block"><h3>How did it feel?</h3><div class="chiprow">${['Comfortable','Tired','Symptoms increased'].map(v=>`<button class="chip ${s.feeling===v?'selected':''}" data-action="feeling" data-value="${v}" aria-pressed="${s.feeling===v}" ${locked?'disabled':''}>${v}</button>`).join('')}</div><label class="field-label" for="notes">Session notes · check again the next morning</label><textarea id="notes" data-field="notes" placeholder="Weights, energy, symptoms, what to change next time…">${esc(s.notes)}</textarea></div>${locked?`<div class="notice">${s.finished?'Completed':'Ended early'} · ${new Date(s.ended).toLocaleDateString(undefined,{day:'numeric',month:'short'})}. ${stats.sets} working sets logged.</div><button class="primary" data-action="${viewed===state.current?'next':'today'}">${viewed!==state.current?'Back to today':state.current===19?'View progress':'Continue to Day '+(state.current+2)} ${icons.arrow}</button>`:`<button class="primary" data-action="finish">Finish session ${icons.check}</button><p class="help">You can end early. Only completed steps are counted.</p>`}<button class="secondary" data-action="whatsapp" style="margin-top:14px">Send to WhatsApp ↗</button>`;updateTimerUI()}
function weekAdvice(n){return ['Start with two controlled sets and a comfortable load.','Keep the weight; add one rep within the range after two well-tolerated sessions.','At the top of the rep range for two well-tolerated sessions? Try the smallest load increase.','Recovery week: one set per exercise, lighter loads and easy cardio.'][Math.floor(n/5)]}
function toggleSet(k){const s=currentSession();if(s.ended)return;const max=dayPlan(viewed,s.mode).ex.length;if(!/^\d+-\d+$/.test(k)||+k.split('-')[0]>=max||+k.split('-')[1]>=setCount(viewed,s))return;s.sets[k]=!s.sets[k];save();if(s.sets[k])startTimer();const openIndices=Array.from(document.querySelectorAll('.block[open]')).map(el=>el.querySelector('h3')?.textContent);renderWorkout();document.querySelectorAll('details.block').forEach(el=>{if(openIndices.includes(el.querySelector('h3')?.textContent))el.open=true})}
function toggleTask(id){const s=currentSession();if(s.ended||!tasksFor(viewed,s).some(t=>t.id===id))return;s.tasks[id]=!s.tasks[id];save();renderWorkout()}
function startTimer(){timerEnd=Date.now()+90000;if(timerInterval)clearInterval(timerInterval);timerInterval=setInterval(updateTimerUI,1000)}
function stopTimer(){timerEnd=0;clearInterval(timerInterval);timerInterval=null;if($('rest'))$('rest').hidden=true}
function updateTimerUI(){if(!$('rest'))return;let secs=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));$('rest').hidden=!secs;if($('restTime'))$('restTime').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');if(timerEnd&&secs===0){stopTimer();toast('Rest complete. Take longer if you need it.')}}
function finish(){const stats=sessionStats(viewed);openSheet(`<span class="overline">Day ${formatDay(viewed)}</span><h2 id="sheetTitle">${stats.done===stats.total?'All done, Thara.':'Finish here for today?'}</h2><p class="muted">${stats.done} of ${stats.total} steps logged${stats.sets?', including '+stats.sets+' working sets':''}.</p><p class="small muted">${stats.done===stats.total?'Save this session to your journal.':'This will be saved as ended early, rather than a completed day. No need to make up missed work.'}</p><button class="primary" data-action="confirmFinish">Save session ${icons.check}</button><button class="secondary" data-action="close">Back to workout</button>`)}
function confirmFinish(){const s=currentSession(),stats=sessionStats(viewed);s.ended=new Date().toISOString();s.finished=stats.done===stats.total?s.ended:null;save();stopTimer();closeSheet();screen='workout';render();window.scrollTo(0,0)}
function nextDay(){if(state.current===19){screen='progress';render();return}if(!getSession().ended){toast('Finish or end your current session first.');return}state.current++;save();viewed=state.current;screen='today';render();window.scrollTo(0,0)}
function renderProgress(){let completed=0,sets=0,minutes=0;Object.keys(state.sessions).forEach(k=>{const s=state.sessions[k];if(s.finished)completed++;const stats=sessionStats(+k);sets+=stats.sets;minutes+=stats.cardio});$('main').innerHTML=`<span class="overline">Your journal</span><h1>Little by little.</h1><p class="muted small">Your own work, recorded one session at a time.</p><div class="metrics"><div class="metric"><strong>${completed}<span style="font-size:17px"> / 20</span></strong><span>Days completed</span></div><div class="metric"><strong>${sets}</strong><span>Sets logged</span></div><div class="metric"><strong>${minutes}</strong><span>Cardio minutes</span></div></div><h3>Four weeks, at your pace</h3>${[0,1,2,3].map(w=>`<div class="flex section-head"><span class="overline">Week ${w+1}</span><span class="muted small">${['Find your starting point','Build repetitions','Add load carefully','Recover & review'][w]}</span></div>${weekStrip(w*5+(Math.floor(state.current/5)===w?state.current%5:0))}`).join('')}<div class="section-head"><h3>Recent sessions</h3></div>${Object.keys(state.sessions).filter(k=>state.sessions[k].started).sort((a,b)=>+b-+a).map(k=>{const s=state.sessions[k],p=dayPlan(+k,s.mode),st=sessionStats(+k);return `<div class="history-item"><div class="flex"><strong>Day ${+k+1} · ${p.title}</strong><span class="badge">${s.finished?'Complete':s.ended?'Ended early':'In progress'}</span></div><p class="small muted">${st.sets} sets · ${st.cardio} cardio min${s.feeling?' · '+esc(s.feeling):''}</p><button class="text-button" data-action="review" data-n="${k}">View session →</button></div>`}).join('')||'<p class="empty">Nothing logged yet. Start Day 1 and your progress will appear here.</p>'}<p class="help">Saved only in this browser. Use Export in the menu to keep a backup or move your journal to another phone.</p>`}
function preview(n){if(n===state.current){closeSheet();screen='today';render();return}const p=DAYS[n%5],s=state.sessions[n];if(s?.started){viewed=n;screen='workout';closeSheet();render();window.scrollTo(0,0);return}openSheet(`<span class="overline">Day ${formatDay(n)} · Week ${Math.floor(n/5)+1}</span><h2 id="sheetTitle">${p.title}</h2><p class="muted">${p.subtitle}</p><p class="small">${weekAdvice(n)}</p><div style="border-block:1px solid var(--line);margin:18px 0">${p.ex.map((e,i)=>`<p class="small">${i+1}. ${e[0]} <span class="muted">· ${e[1]}</span> ${demoLink(e[0])}</p>`).join('')}</div><p class="help">This is a preview. Finish your current day to move on. Exercise choices adapt to your check-in.</p><button class="primary" data-action="close">Got it</button>`)}
function approach(){openSheet(`<span class="overline">The plan</span><h2 id="sheetTitle">Your weekly plan.</h2><p class="small">Lower / upper / lower / upper / full body. Rest on weekends or whenever you need it. Day numbers advance only when you choose.</p><p class="small">Cardio goal: 20–30 min. Core goal: up to 15 min on Days 1, 3 and 5 of each week. These are gradual targets, not requirements during symptoms.</p><p class="small">Keep 3–4 repetitions in reserve. Increase reps or weight only after two well-tolerated sessions with no flare afterward or the next morning. Change one thing at a time. The final week is lighter.</p><details><summary>Back pain & getting help</summary><p>Recurring pain with lower-body training deserves assessment by a physiotherapist or clinician. The gentle mode pauses loaded lower-body work; it is not a rehabilitation prescription. Adjust or stop movements that worsen or spread symptoms.</p><p>Seek emergency care for new bladder or bowel problems, groin numbness, or weakness/numbness in both legs. Rapidly worsening severe pain, fever or feeling unwell needs urgent assessment.</p><a href="https://www.nhs.uk/conditions/back-pain/" target="_blank" rel="noopener">NHS guidance ↗</a></details><button class="secondary" data-action="close" style="margin-top:22px">Close</button>`)}
function whatsappText(n=screen==='workout'?viewed:state.current){const s=getSession(n),p=s.started?dayPlan(n,s.mode):DAYS[n%5],st=sessionStats(n),lines=['Thara · Day '+(n+1)+' / Week '+(Math.floor(n/5)+1),p.title+' — '+p.subtitle,''];if(p.recovery){lines.push('Light movement / recovery session. No loaded workout listed.')}else{lines.push(...p.ex.map((e,i)=>{let logs=[];for(let j=0;j<setCount(n,s);j++){const k=i+'-'+j;if(s.sets[k])logs.push((s.loads[k]!==undefined&&s.loads[k]!==''?s.loads[k]+' kg':'load not logged')+' × '+(s.reps[k]||'reps not logged'))}return (i+1)+'. '+e[0]+' · '+(s.started?setCount(n,s):Math.floor(n/5)===3?1:2)+' sets × '+e[1]+' reps'+(logs.length?'\n   Logged: '+logs.join('; '):'')}));lines.push('',s.mode==='caution'?'Cardio: optional comfortable walking.':'Cardio goal: 20–30 min at an easy conversational pace.');if(s.mode!=='caution'&&[0,2,4].includes(n%5))lines.push('Core: up to 15 min, as tolerated.')}if(s.started)lines.push('',(s.finished?'Complete':s.ended?'Ended early':'In progress')+' · '+st.done+'/'+st.total+' steps logged',st.cardio+' cardio minutes logged');lines.push('','Open the training journal: '+location.origin+location.pathname);return lines.join('\n')}
function sendWhatsApp(){window.open('https://wa.me/?text='+encodeURIComponent(whatsappText()),'_blank','noopener,noreferrer')}
function settings(){openSheet(`<span class="overline">Your journal</span><h2 id="sheetTitle">Saved on your phone.</h2><p class="muted small">No sign-in. No uploads. Your workouts and notes stay in this browser; they won’t sync automatically. Clearing browser data can erase them.</p><div class="backup"><button class="secondary" data-action="export">Export backup</button><button class="secondary" data-action="import">Restore backup</button></div><input id="backupFile" type="file" accept="application/json,.json" hidden><p class="help">To move phones, export the backup, then restore it in the new browser. Keep the backup private if it includes personal notes.</p><button class="text-button" data-action="approach">About the training plan ↗</button>`)}
function exportData(){const data=new Blob([JSON.stringify({format:STORE,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='thara-training-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded.')}
function validBackup(v){if(!v||v.format!==STORE||!Number.isInteger(v.current)||v.current<0||v.current>19||!v.sessions||typeof v.sessions!=='object'||Array.isArray(v.sessions))return false;return Object.entries(v.sessions).every(([k,s])=>/^\d+$/.test(k)&&+k<20&&s&&typeof s==='object'&&s.sets&&s.tasks&&s.loads&&s.reps&&typeof s.notes==='string'&&[null,'ready','caution','flare'].includes(s.mode))}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3000)}
// Exercise support, flexible scheduling and device-local activity estimates.
const PHOTOS='https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/';
