const originalGetSession=getSession;getSession=function(n=state.current){const s=originalGetSession(n);s.levels=s.levels||{};s.extras=s.extras||{};s.activity=s.activity||{};s.variants=s.variants||{};s.skills=s.skills||{};return s};
function demoPhotos(photo,caption='',source='Free Exercise DB'){if(!photo)return '';const direct=photo.startsWith('https://'),urls=direct?[photo]:[PHOTOS+photo+'/0.jpg',PHOTOS+photo+'/1.jpg'];return `<figure class="demo-photos"><div class="photo-pair ${direct?'single-photo':''}">${urls.map((url,i)=>`<img src="${url}" alt="${esc(caption||photo.replaceAll('_',' '))}, ${direct?'movement sequence':'position '+(i+1)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true;this.parentElement.nextElementSibling.hidden=false">`).join('')}</div><p hidden class="help">Image unavailable. Use the demonstration link above.</p><figcaption>${esc(caption||'Movement reference; follow the setup and supports described here.')} <span>Images: ${source==='NHS'?'<a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener">NHS</a>':'<a href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noopener">Free Exercise DB (public domain)</a>'}.</span></figcaption></figure>`}
function exerciseTools(n,s,e,i){const h=EXERCISE_HELP[e[0]],level=s.mode==='ready'?(s.levels[i]||0):0;if(!h)return '';return `${demoPhotos(h.photo,h.caption||'',h.source)}<div class="level-controls" role="group" aria-label="${esc(e[0])} difficulty">${['Easy','Intermediate','Hard'].map((v,l)=>`<button class="chip ${level===l?'selected':''}" data-action="level" data-ex="${i}" data-level="${l}" aria-pressed="${level===l}" ${s.ended||s.mode!=='ready'&&l>0?'disabled':''}>${v}</button>`).join('')}</div><p class="level-note"><strong>${['Easy','Intermediate','Hard'][level]}:</strong> ${h.levels[level]}. ${level===2?'Change tempo or control before adding weight.':''}</p><details class="form-tips"><summary>Posture & common corrections</summary><ul>${h.tips.map(t=>'<li>'+t+'</li>').join('')}</ul></details><p class="load-advice">${loadGuidance(n,i)}</p>`}
function changeLevel(i,level){const s=currentSession();if(s.ended||![0,1,2].includes(level)||s.mode!=='ready'&&level>0)return;const old=s.levels[i]||0;if(old===level)return;const count=setCount(viewed,s);let snapshot={sets:{},loads:{},reps:{}};for(let j=0;j<count;j++){const k=i+'-'+j;for(const f of ['sets','loads','reps']){snapshot[f][k]=s[f][k];delete s[f][k]}}s.variants[i+'-'+old]=snapshot;const prior=s.variants[i+'-'+level];if(prior)for(const f of ['sets','loads','reps'])Object.assign(s[f],prior[f]);s.levels[i]=level;save();renderWorkout()}
function loadGuidance(n,i){const s=getSession(n),base=dayPlan(n,s.mode).ex[i];if(!base)return '';if(s.mode!=='ready')return 'Load progression is paused while symptoms recur.';if(Math.floor(n/5)===3)return 'Week 4: reduce load by about 10–20%, or keep one comfortable set. No load increase this week.';const name=base[0],level=s.levels[i]||0,records=Object.entries(state.sessions).filter(([k,v])=>Number(k)!==n&&v.ended&&v.started&&v.feeling==='Comfortable'&&v.nextMorning==='Comfortable').map(([k,v])=>({n:Number(k),s:getSession(Number(k))})).sort((a,b)=>new Date(b.s.ended)-new Date(a.s.ended));const matches=[];for(const r of records){const idx=dayPlan(r.n,r.s.mode).ex.findIndex(e=>e[0]===name);if(idx<0||(r.s.levels[idx]||0)!==level)continue;const top=Number(base[1].match(/\d+/g).slice(-1)[0]);const count=setCount(r.n,r.s);const rows=Array.from({length:count},(_,j)=>({done:r.s.sets[idx+'-'+j],load:r.s.loads[idx+'-'+j],reps:r.s.reps[idx+'-'+j]}));if(rows.every(x=>x.done&&Number(x.reps)>=top&&x.load!==''&&Number(x.load)>0)&&rows.every(x=>Number(x.load)===Number(rows[0].load)))matches.push(Number(rows[0].load));else break;if(matches.length===2)break}if(matches.length===2&&matches[0]===matches[1])return `Two comfortable sessions at the top of the rep range, including the next morning. Last load: ${matches[0]} kg. Consider the smallest available increase, roughly 2–5%; keep reps at the lower end. If the machine jump is larger, keep the same load. No automatic increase.`;return 'Weekly load check: keep the same load until all sets reach the top of the rep range in two comfortable sessions, including the next morning. Then consider a small 2–5% increase. Do not add weight and change level together.'}
const ROUTINES={
lower:{warm:[['Easy march','Stay upright; use a support if needed.',null],['Ankle circles','Small circles, 30 seconds per side.','Ankle_Circles'],['Small hip circles','Hands on hips or a rail; keep the range gentle.','Standing_Hip_Circles'],['Supported knee bends','A shallow bend only; knees follow toes.','https://assets.nhs.uk/nhsuk-cms/images/STRENGTH_EXERCISES-_mini-squats.width-320.jpg'],['Sit-to-stand practice','Use a higher seat and comfortable hand support.',NHS_SIT]],cool:[['Slow walk','Let breathing settle.',null],['Calf stretch','25 seconds per side with a wall; do not bounce.','Calf_Stretch_Hands_Against_Wall'],['Supported quad stretch','Hold support, bring heel gently toward seat; skip if balance is uncertain.','Quad_Stretch'],['Hamstring stretch','Heel on floor, small hip hinge, comfortable back.','Standing_Hamstring_and_Calf_Stretch'],['Hip-flexor stretch','Short split stance; stay tall, no back arch.','Standing_Hip_Flexors']]},
upper:{warm:[['Easy march','Keep a comfortable pace.',null],['Shoulder rolls','Slow backward circles; neck relaxed.',null],['Small arm circles','30 seconds each direction; no forced range.','Arm_Circles'],['Gentle chest opening','Move arms apart smoothly; keep ribs down.','Dynamic_Chest_Stretch'],['Light row / press practice','Very light practice repetitions, no strain.','Leverage_Chest_Press']],cool:[['Slow walk','Breathe normally as effort eases.',null],['Cross-body shoulder stretch','25 seconds per side; shoulder stays low.','Shoulder_Stretch'],['Gentle chest stretch','Support the hand at comfortable height and turn slightly away.','Chest_And_Front_Of_Shoulder_Stretch'],['Triceps stretch','25 seconds per side; avoid pushing on your neck.','Triceps_Stretch'],['Relaxed arm opening','Keep arms low and breathe without forcing the stretch.','Dynamic_Chest_Stretch']]},
full:{warm:[['Easy march','Build warmth gradually.',null],['Ankle circles','30 seconds each side.','Ankle_Circles'],['Small arm circles','Stay within a comfortable arc.','Arm_Circles'],['Supported sit-to-stand','Gentle practice; no weights.',NHS_SIT],['Light row / press practice','Keep the load very easy.','Leverage_Iso_Row']],cool:[['Slow walk','Let your breathing settle.',null],['Calf stretch','25 seconds each side.','Calf_Stretch_Hands_Against_Wall'],['Hamstring stretch','A small hip hinge, no rounding or forcing.','Standing_Hamstring_and_Calf_Stretch'],['Cross-body shoulder stretch','25 seconds each side.','Shoulder_Stretch'],['Gentle chest stretch','Comfortable range; no back arch.','Chest_And_Front_Of_Shoulder_Stretch']]}
};
function routineFor(n,type){const group=n%5===4?'full':[0,2].includes(n%5)?'lower':'upper';return ROUTINES[group][type]}
function routineHTML(n,type){const s=getSession(n),rows=routineFor(n,type),id=type==='warm'?'warmup':'cooldown';return `<details class="routine" ${type==='warm'?'open':''}><summary><strong>${type==='warm'?'Start · 5-minute warm-up & mobility':'Finish · 5-minute cool-down stretches'}</strong></summary><p class="help">${type==='warm'?'Five gentle one-minute steps. Use moving stretches before lifting; add light practice sets as needed.':'One minute to slow down, then gentle holds. Aim for 25 seconds per side, with time to switch. No bouncing or forcing.'} These are minimum guides, not a reason to rush.</p><ol class="routine-list">${rows.map((r,i)=>`<li><div class="flex"><strong>${i+1}. ${r[0]}</strong><span class="muted small">1 min</span></div><p class="small muted">${r[1]}</p>${r[2]?`<details><summary>Show movement</summary>${demoPhotos(r[2],'Movement reference; keep the gentler setup described above.',r[2].startsWith('https://assets.nhs')?'NHS':undefined)}</details>`:''}</li>`).join('')}</ol><button class="secondary" data-action="routineTimer" data-type="${type}" ${s.ended?'disabled':''}>Start 5-minute guide</button><div id="routineClock-${type}" class="routine-clock" aria-live="polite"></div>${type==='warm'?'<details class="video-demo"><summary>Watch the NHS 5-minute warm-up here</summary><iframe loading="lazy" src="https://www.youtube-nocookie.com/embed/oLu9kwDzBdg" title="NHS basic five minute warm-up" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="help">If YouTube blocks embedded playback, <a href="https://www.youtube.com/watch?v=oLu9kwDzBdg" target="_blank" rel="noopener">open the NHS video</a>.</p></details>':''}</details>`}
let routineTimer=null,routineGuide=null;function startRoutine(type){clearInterval(routineTimer);routineGuide={type,day:viewed,end:Date.now()+300000};paintRoutine();routineTimer=setInterval(paintRoutine,1000)}function paintRoutine(){if(!routineGuide)return;const g=routineGuide,remaining=Math.max(0,Math.ceil((g.end-Date.now())/1000)),step=Math.min(4,Math.floor((300-remaining)/60));const el=$('routineClock-'+g.type);if(el&&viewed===g.day)el.innerHTML=remaining?`<strong>${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}</strong><span>${routineFor(g.day,g.type)[step][0]}</span><button class="text-button" data-action="routineStop">Stop guide</button>`:'Guide finished. Mark the routine complete if you did it comfortably.';if(!remaining){clearInterval(routineTimer);routineGuide=null}}function stopRoutine(){clearInterval(routineTimer);routineGuide=null;for(const type of ['warm','cool'])if($('routineClock-'+type))$('routineClock-'+type).textContent='Guide stopped. Only log the time you completed.'}
const baseTasksFor=tasksFor;tasksFor=function(n,s){return baseTasksFor(n,s).map(t=>t.id==='warmup'?{...t,name:'5-minute warm-up completed',detail:'Day-specific movement and mobility above, plus any needed practice sets.'}:t.id==='cooldown'?{...t,name:'5-minute cool-down completed',detail:'Slow down first, then the area-specific stretches above.'}:t)};
const baseTaskHTML=taskHTML;taskHTML=function(t,s){if(t.id==='warmup')return routineHTML(viewed,'warm')+baseTaskHTML(t,s);if(t.id==='cooldown')return routineHTML(viewed,'cool')+baseTaskHTML(t,s);if(t.id==='core')return coreHTML(s)+`<button class="task-check" data-action="task" data-id="core" aria-pressed="${!!s.tasks.core}" ${s.ended?'disabled':''}><span class="square">✓</span><span>Core circuit completed<small>Only check if you did the selected version comfortably.</small></span></button>`;return baseTaskHTML(t,s)};
const CORE_LEVELS=[{name:'Easy',detail:'Dead bug: heel slide, 6/side. Bird dog: arm-only reach, 6/side. Plank: wall plank, 10–15 seconds.',plank:'Wall plank'},{name:'Intermediate',detail:'Dead bug: bent-knee heel tap, 6/side. Bird dog: opposite arm and leg, 6/side. Plank: forearms with knees down, 15–20 seconds.',plank:'Knee plank'},{name:'Hard',detail:'Dead bug: longer arm/leg reach, 6/side. Bird dog: 3-second controlled hold, 6/side. Plank: forearms and toes, 20–30 seconds.',plank:'Forearm plank'}];
function birdDogGraphic(){return `<figure class="demo-photos"><svg viewBox="0 0 460 165" role="img" aria-label="Bird dog positions: on hands and knees, then reach an opposite arm and leg while keeping hips level" style="width:100%;background:#fff;border-radius:10px"><g fill="none" stroke="#733e46" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"><path stroke="#ddd7cd" stroke-width="2" d="M15 132H445"/><circle cx="150" cy="47" r="11"/><path d="M138 59L85 62L60 112L84 113M131 62L145 112M83 63L103 110L123 112"/><circle cx="350" cy="47" r="11"/><path d="M338 59L285 62M338 60L377 48L410 48M332 63L346 112M285 63L302 111L324 112M285 62L256 62L224 62"/></g><text x="50" y="155" font-size="12" fill="#75746e">Start: hands and knees</text><text x="240" y="155" font-size="12" fill="#75746e">Opposite arm and leg reach</text></svg><figcaption>Schematic side view. Keep both hips level; the Easy version reaches one arm only.</figcaption></figure>`}
function coreHTML(s){const level=s.mode==='ready'?(s.skills.core||0):0;return `<details class="routine" open><summary><strong>Core · gradual plank progression</strong></summary><div class="level-controls">${CORE_LEVELS.map((l,i)=>`<button class="chip ${level===i?'selected':''}" data-action="skill" data-skill="core" data-level="${i}" aria-pressed="${level===i}" ${s.ended?'disabled':''}>${l.name}</button>`).join('')}</div><p class="small">${CORE_LEVELS[level].detail}</p><p class="help">Start with one round. Build to three only with comfortable form. Rest 30–60 seconds between movements; allow up to 15 minutes. Ribs stay over pelvis; stop if the back sags or symptoms increase. This replaces the previous core circuit.</p>${demoPhotos('Dead_Bug','Dead bug reference. Use the shorter reach for Easy.')}${level===0?demoPhotos(NHS_WALL,'Wall support reference: for a wall plank, keep elbows straight and hold still.','NHS'):demoPhotos('Plank',level===1?'Full plank reference; lower both knees for the Intermediate version.':'Forearms under shoulders; maintain a comfortable straight line.')}${birdDogGraphic()}<details><summary>Bird dog form</summary><p class="small">Hands below shoulders, knees below hips. Keep pelvis level and reach long, not high. Easy uses one arm only; progress to opposite arm and leg.</p></details></details>`}
function extrasHTML(n,s){if(s.mode!=='ready'||dayPlan(n,s.mode).recovery)return '<p class="help">Extra circuits and progression skills are paused while symptoms recur.</p>';const focus=s.extraFocus||'core';return `<details class="routine"><summary><strong>Optional · 10–15 minute focus</strong></summary><p class="help">Choose one add-on, not all three. Skip it if tired. On a scheduled core day this is an alternative, not extra core volume. These train an area; they do not selectively burn fat there.</p><div class="level-controls">${[['core','Core'],['hips','Hips & calves'],['shoulders','Shoulders & arms']].map(([id,label])=>`<button class="chip ${focus===id?'selected':''}" data-action="extraFocus" data-focus="${id}" ${s.ended?'disabled':''}>${label}</button>`).join('')}</div><p class="small">${focus==='core'?'Use the selected core level: dead bug, bird dog and plank. One to three rounds, resting 30–60 seconds.':focus==='hips'?'Two easy rounds: supported calf raises × 12, seated hip abduction × 12, calf and hip-flexor stretches 20 seconds per side. Rest about 60 seconds between exercises.':'Two easy rounds: seated lateral raise × 10, supported biceps curl × 10, cross-body shoulder and chest stretches 20 seconds per side. Rest about 60 seconds between exercises.'}</p>${focus==='core'&&![0,2,4].includes(n%5)?coreHTML(s):''}<button class="task-check" data-action="extraDone" aria-pressed="${!!s.extras[focus]}" ${s.ended?'disabled':''}><span class="square">✓</span><span>Add-on completed<small>Optional: does not affect the main session completion score.</small></span></button></details><details class="routine"><summary><strong>Push-up skill ladder</strong></summary><p class="help">Optional upper-body skill practice instead of an extra pressing exercise. Choose one version. Progress after two comfortable sessions at the top of the range, not by calendar alone.</p><div class="level-controls">${['Easy','Intermediate','Hard'].map((v,i)=>`<button class="chip ${(s.skills.pushup||0)===i?'selected':''}" data-action="skill" data-skill="pushup" data-level="${i}" ${s.ended?'disabled':''}>${v}</button>`).join('')}</div><p class="small">${['Wall push-up: 1–2 × 5–10. Keep body straight; hands near chest height.','Incline push-up on a fixed high bench: 1–2 × 5–10. Lower the bench only as strength allows.','Floor push-up: 1–2 × 5–10. Stop before the hips sag or shoulders shrug.'][s.skills.pushup||0]}</p>${(s.skills.pushup||0)===0?demoPhotos(NHS_WALL,'Wall push-up movement sequence.','NHS'):demoPhotos((s.skills.pushup||0)===1?'Incline_Push-Up':'Pushups','Keep ribs and pelvis aligned; elbows angle comfortably away from the torso.')}<p class="help">Correction: if your lower back sags, move to a higher support. If your head reaches first, keep your neck in line with your torso.</p><button class="task-check" data-action="skillDone" aria-pressed="${!!s.skills.pushupDone}" ${s.ended?'disabled':''}><span class="square">✓</span><span>Skill practice logged</span></button></details>`}
function calorieEstimate(n){const s=getSession(n),w=Number(s.activity.bodyweight),strength=Number(s.activity.strength)||0,core=Number(s.activity.core)||0,extra=Number(s.activity.extra)||0,mobility=Number(s.activity.mobility)||0,cardio=Number(s.cardio)||0;const met=s.activity.pace==='moderate'?3.8:3;const minutes=strength+core+extra+mobility+cardio;if(w<30||w>250||!minutes)return {kcal:null,minutes};return {kcal:Math.round(w*(3.5*(strength+core+extra)+2.3*mobility+met*cardio)/60),minutes}}
function calorieHTML(n,s){const est=calorieEstimate(n);return `<details class="routine calorie-panel" ${s.activity.bodyweight?'open':''}><summary><strong>Tap calorie tracker <span class="kcal">${est.kcal===null?'Set up':est.kcal+' kcal est.'}</span></strong></summary><p class="help">A rough MET-based estimate, not a wearable measurement. Enter actual, non-overlapping minutes. Includes resting energy during exercise. No calorie target.</p><div class="activity-grid">${[['bodyweight','Body weight','kg'],['strength','Strength time','min'],['core','Core time','min'],['extra','Add-on / skills','min'],['mobility','Warm-up + stretches','min']].map(([key,label,unit])=>`<div><span class="small">${label}</span><button class="number-field" data-action="activityNumber" data-key="${key}" aria-label="Choose ${label}" ${s.ended?'disabled':''}>${esc(s.activity[key]??'—')} <small>${unit}</small></button></div>`).join('')}<div><span class="small">Cardio time</span><button class="number-field" data-action="number" data-field="cardio" ${s.ended?'disabled':''}>${s.cardio||0} <small>min</small></button></div></div><p class="small">Cardio pace</p><div class="level-controls">${[['easy','Easy flat walk'],['moderate','Moderate walk']].map(([id,label])=>`<button class="chip ${(s.activity.pace||'easy')===id?'selected':''}" data-action="pace" data-pace="${id}" ${s.ended?'disabled':''}>${label}</button>`).join('')}</div><p class="small"><strong>${est.kcal===null?'Choose body weight and log activity minutes.':est.kcal+' estimated kcal · '+est.minutes+' minutes logged.'}</strong></p><p class="help">For cycling or another activity, this walk-based cardio estimate will not match. Do not log core or skill time twice as both strength and add-on time. <a href="https://pacompendium.com/conditioning-exercise/" target="_blank" rel="noopener">MET source</a> · Formula: Σ(MET × kg × minutes ÷ 60). Strength/core/add-on 3.5 MET; gentle mobility 2.3; walking 3.0 or 3.8. Individual energy use varies.</p></details>`}
function openActivityNumber(key){const s=currentSession();if(s.ended)return;const weight=key==='bodyweight',values=weight?Array.from({length:441},(_,i)=>30+i*.5):Array.from({length:181},(_,i)=>i),existing=s.activity[key],chosen=Number(existing??(weight?60:0));numberPicker={field:'activity',key,values,index:Math.max(0,values.indexOf(chosen)),opened:[]};openSheet(`<h2 id="sheetTitle">${weight?'Body weight (kg)':'Actual minutes logged'}</h2><p class="small muted">${weight?'This stays on your device.':'Choose only the time you actually did, without double counting.'}</p><div class="wheel-wrap"><div class="wheel-band"></div><div id="numberWheel" class="number-wheel" role="listbox" aria-label="${weight?'Body weight':'Minutes'}" tabindex="0">${values.map((v,i)=>`<div id="wheel-option-${i}" class="wheel-option" role="option" aria-selected="${i===numberPicker.index}" data-action="wheelOption" data-index="${i}">${v}<span>${weight?'kg':'min'}</span></div>`).join('')}</div></div><div class="picker-actions flex"><button class="secondary" data-action="numberClear">Clear</button><button class="primary" data-action="numberDone">Done</button></div>`);const wheel=$('numberWheel');wheel.scrollTop=numberPicker.index*48;wheel.addEventListener('scroll',()=>{if(numberPicker)setPickerIndex(Math.round(wheel.scrollTop/48))},{passive:true});wheel.addEventListener('keydown',e=>{if(!numberPicker)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();setPickerIndex(numberPicker.index+(e.key==='ArrowDown'?1:-1));wheel.scrollTop=numberPicker.index*48}else if(e.key==='Enter'){e.preventDefault();commitNumberPicker()}})}
const baseCommitNumber=commitNumberPicker;commitNumberPicker=function(clear=false){if(numberPicker?.field!=='activity'){baseCommitNumber(clear);return}const p=numberPicker,s=currentSession();if(s.ended)return;s.activity[p.key]=clear?'':p.values[p.index];if(p.key==='bodyweight')state.bodyweight=s.activity[p.key];save();closeSheet();renderWorkout()};
function selectAnyDay(n){if(!Number.isInteger(n)||n<0||n>19)return;stopTimer();stopRoutine();state.current=n;viewed=n;save();closeSheet();screen='today';render();window.scrollTo(0,0)}
preview=function(n){if(!Number.isInteger(n)||n<0||n>19)return;const p=DAYS[n%5],s=getSession(n);openSheet(`<span class="overline">Day ${formatDay(n)} · Week ${Math.floor(n/5)+1}</span><h2 id="sheetTitle">${p.title}</h2><p class="muted">${p.subtitle}</p><p class="small">${weekAdvice(n)}</p><p class="small">5-minute ${p.short.toLowerCase()} warm-up · ${p.ex.length} exercises · cardio · 5-minute cool-down.</p><p class="help">Choose any day. Switching leaves all other days and their logs untouched. Rest or alternate muscle groups rather than repeating hard sessions back-to-back.</p><button class="primary" data-action="selectDay" data-n="${n}">${s.ended?'Review':s.started?'Resume':'Choose'} Day ${n+1}</button>`)};
const baseHome=renderHome;renderHome=function(){baseHome();$('main').innerHTML=$('main').innerHTML.replace('Days follow your pace, not the calendar. Rest days are yours to take.','Tap any day to choose it. Find all 20 days in Progress; you can start anywhere. Rest days are yours to take.');const s=getSession();if(!s.activity.bodyweight&&state.bodyweight)s.activity.bodyweight=state.bodyweight;};
const baseWorkout=renderWorkout;renderWorkout=function(){baseWorkout();const s=currentSession();if(!s.activity.bodyweight&&state.bodyweight)s.activity.bodyweight=state.bodyweight;let html=$('main').innerHTML;const anchor='<div class="block"><h3>How did it feel?</h3>';html=html.replace(anchor,extrasHTML(viewed,s)+calorieHTML(viewed,s)+anchor);html=html.replace('<label class="field-label" for="notes">',`<p class="small">Next-morning response</p><div class="chiprow">${['Comfortable','Sore / unsure','Symptoms increased'].map(v=>`<button class="chip ${s.nextMorning===v?'selected':''}" data-action="nextMorning" data-value="${v}" aria-pressed="${s.nextMorning===v}">${v}</button>`).join('')}</div><p class="help">Update this after the next morning. Leaving it blank prevents load-increase suggestions.</p><label class="field-label" for="notes">`);$('main').innerHTML=html;paintRoutine();};
const baseProgress=renderProgress;renderProgress=function(){baseProgress();let total=0,logged=0;Object.keys(state.sessions).forEach(k=>{const v=calorieEstimate(+k);if(v.kcal!==null){total+=v.kcal;logged++}});$('main').innerHTML=$('main').innerHTML.replace('<h3>Four weeks, at your pace</h3>',`<div class="notice">${logged?total+' estimated kcal across '+logged+' logged sessions.':'Calorie estimates appear after body weight and actual activity minutes are logged.'} <span class="small">Estimates, not measured burn.</span></div><h3>Choose any day</h3>`);};
const baseWhatsApp=whatsappText;whatsappText=function(n=screen==='workout'?viewed:state.current){return baseWhatsApp(n)+'\n5-minute warm-up and 5-minute cool-down included. Difficulty choices and optional focus modules are in the journal.'};
// New controls use the same saved session records; existing workouts remain intact.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=currentSession();if(a==='selectDay')selectAnyDay(Number(b.dataset.n));else if(a==='level')changeLevel(Number(b.dataset.ex),Number(b.dataset.level));else if(a==='routineTimer')startRoutine(b.dataset.type);else if(a==='routineStop')stopRoutine();else if(a==='activityNumber')openActivityNumber(b.dataset.key);else if(a==='pace'&&!s.ended){s.activity.pace=b.dataset.pace;save();renderWorkout()}else if(a==='extraFocus'&&!s.ended){s.extraFocus=b.dataset.focus;save();renderWorkout()}else if(a==='extraDone'&&!s.ended){const f=s.extraFocus||'core';s.extras[f]=!s.extras[f];save();renderWorkout()}else if(a==='skill'&&!s.ended){const level=Number(b.dataset.level);if([0,1,2].includes(level)){s.skills[b.dataset.skill]=level;save();renderWorkout()}}else if(a==='skillDone'&&!s.ended){s.skills.pushupDone=!s.skills.pushupDone;save();renderWorkout()}else if(a==='nextMorning'){s.nextMorning=b.dataset.value;save();renderWorkout()}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='today'){screen='today';render();window.scrollTo(0,0)}else if(a==='progress'){screen='progress';render();window.scrollTo(0,0)}else if(a==='number')openNumberPicker(b.dataset.field,b.dataset.key);else if(a==='numberDone')commitNumberPicker();else if(a==='numberClear')commitNumberPicker(true);else if(a==='wheelOption'){setPickerIndex(Number(b.dataset.index));$('numberWheel').scrollTo({top:numberPicker.index*48,behavior:'smooth'})}else if(a==='settings')settings();else if(a==='approach')approach();else if(a==='close')closeSheet();else if(a==='start'){const s=getSession();viewed=state.current;if(!s.started)checkin();else{screen='workout';render();window.scrollTo(0,0)}}else if(a==='checkin')checkin();else if(a==='mode')startMode(b.dataset.mode);else if(a==='task')toggleTask(b.dataset.id);else if(a==='set')toggleSet(b.dataset.key);else if(a==='timerStop')stopTimer();else if(a==='finish')finish();else if(a==='confirmFinish')confirmFinish();else if(a==='next')nextDay();else if(a==='preview')preview(+b.dataset.n);else if(a==='review'){viewed=+b.dataset.n;screen='workout';render();window.scrollTo(0,0)}else if(a==='feeling'){currentSession().feeling=b.dataset.value;save();document.querySelectorAll('.chip').forEach(c=>{const active=c.dataset.value===b.dataset.value;c.classList.toggle('selected',active);c.setAttribute('aria-pressed',String(active))});if(b.dataset.value==='Symptoms increased')toast('Stop provoking movements. Record the symptoms and seek advice.')}else if(a==='whatsapp')sendWhatsApp();else if(a==='export')exportData();else if(a==='import')$('backupFile').click()});
document.addEventListener('input',e=>{const f=e.target.dataset.field;if(!f)return;const s=currentSession();if(f==='notes')s.notes=e.target.value.slice(0,10000);else if(s.ended)return;else if(f==='cardio')s.cardio=Math.min(300,Math.max(0,Number(e.target.value)||0));else if(f==='load')s.loads[e.target.dataset.key]=e.target.value===''?'':Math.min(1000,Math.max(0,Number(e.target.value)||0));else if(f==='reps')s.reps[e.target.dataset.key]=e.target.value===''?'':Math.min(100,Math.max(1,Math.round(Number(e.target.value)||1)));save()});
document.addEventListener('change',async e=>{if(e.target.id!=='backupFile'||!e.target.files[0])return;try{if(e.target.files[0].size>1000000)throw Error();const data=JSON.parse(await e.target.files[0].text());if(!validBackup(data))throw Error();openSheet('<h2 id="sheetTitle">Replace this journal?</h2><p class="small">Restoring replaces the progress currently saved on this phone. Export your current journal first if you want to keep it.</p><button class="primary" id="confirmRestore">Restore backup</button><button class="secondary" data-action="close">Cancel</button>');$('confirmRestore').onclick=()=>{state={current:data.current,sessions:data.sessions,bodyweight:data.bodyweight};save();stopTimer();closeSheet();screen='today';render();toast('Journal restored.')}}catch{toast('That file isn’t a valid journal backup.')}});
$('overlay').addEventListener('click',e=>{if(e.target===$('overlay'))closeSheet()});document.addEventListener('keydown',e=>{if($('overlay').hidden)return;if(e.key==='Escape')closeSheet();if(e.key==='Tab'){const nodes=Array.from($('sheet').querySelectorAll('button:not([disabled]),a[href],input:not([hidden]),summary'));const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('sheet'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateGreeting()});
setInterval(()=>{updateGreeting();if(screen==='today'&&$('overlay').hidden)renderHome()},60000);render();

